def pack(values):
    previous = None
    count = 0
    result = []
    for value in values:
        if value == previous:
            count += 1
        else:
            if previous is not None:
                result.append((previous, count))
            previous, count = value, 1
    if previous is not None:
        result.append((previous, count))
    return result

