import unittest
from runs import pack

class Runs(unittest.TestCase):
    def test_falsy_and_order(self):
        self.assertEqual(pack([None,None,0,0,'','',None]),[(None,2),(0,2),('',2),(None,1)])
        self.assertEqual(pack([2,1,2]),[(2,1),(1,1),(2,1)])
        self.assertEqual(pack([]),[])
        self.assertEqual(pack([None]),[(None,1)])
    def test_generator_and_unhashable(self):
        self.assertEqual(pack(x for x in [[1],[1],[],[],[2]]),[([1],2),([],2),([2],1)])

if __name__ == '__main__':
    unittest.main()

